

      const buildTaskNoticeFaceBlocks = (style = "face") => {
        if (!taskUserNoticeFace) {
          return;
        }
        const faceStyle = normalizeTaskNoticeStyle(style);
        stopTaskNoticeFaceGaze();
        taskUserNoticeFace.textContent = "";
        taskUserNoticeFace.classList.add("is-native-face");
        taskNoticeFaceScene = null;
        const frame = document.createElement("iframe");
        const faceSource = faceStyle === "face1" ? "/face-1.html" : "/face-2.html";
        const faceSourceUrl = `${faceSource}${faceSource.includes("?") ? "&" : "?"}noticeFace=1`;
        frame.className = "ft-task-ai-face-frame";
        frame.title = faceStyle === "face1" ? "AI face 1" : "AI face 2";
        frame.setAttribute("aria-hidden", "true");
        frame.setAttribute("loading", "eager");
        frame.setAttribute("referrerpolicy", "no-referrer");
        frame.setAttribute("allow", "autoplay; fullscreen");
        frame.setAttribute("allowtransparency", "true");
        frame.allowTransparency = "true";
        frame.addEventListener("load", () => {
          postTaskNoticeNativeFaceMessage({
            type: "ft-face-speaking",
            value: taskUserNotice ? taskUserNotice.classList.contains("is-speaking") : false,
          });
        });
        frame.src = faceSourceUrl;
        taskUserNoticeFace.appendChild(frame);
        return;
        const face1SourceBase64 = "";
        const face2SourceBase64 = "";
        const faceSourceBase64 = faceStyle === "face1" ? face1SourceBase64 : face2SourceBase64;
        frame.className = "ft-task-ai-face-frame";
        frame.title = faceStyle === "face1" ? "AI face 1" : "AI face 2";
        frame.setAttribute("aria-hidden", "true");
        frame.setAttribute("loading", "eager");
        frame.setAttribute("referrerpolicy", "no-referrer");
        frame.setAttribute("allow", "autoplay; fullscreen");
        frame.setAttribute("allowtransparency", "true");
        frame.allowTransparency = "true";
        frame.addEventListener("load", () => {
          postTaskNoticeNativeFaceMessage({
            type: "ft-face-speaking",
            value: taskUserNotice ? taskUserNotice.classList.contains("is-speaking") : false,
          });
        });
        try {
          const binary = window.atob(faceSourceBase64);
          const bytes = new Uint8Array(binary.length);
          for (let i = 0; i < binary.length; i += 1) {
            bytes[i] = binary.charCodeAt(i);
          }
          let faceHtml = new TextDecoder("utf-8").decode(bytes);
          faceHtml = faceHtml
            .replace("background-color: #01040f;", "background-color: transparent;")
            .replace("</style>", "html, body, #canvas-container, canvas { background: transparent !important; background-color: transparent !important; } body.notice-face-embed::before { content: ''; position: fixed; inset: 0; z-index: 0; pointer-events: none; background: radial-gradient(circle at 50% 48%, rgba(1, 4, 15, 0.78) 0%, rgba(1, 4, 15, 0.56) 31%, rgba(1, 4, 15, 0.22) 54%, rgba(1, 4, 15, 0) 76%); } #canvas-container { z-index: 1; } canvas { display: block; }</style>")
            .replace("<body>", "<body class=\"notice-face-embed\">")
            .replace("const renderer = new THREE.WebGLRenderer({ antialias: true });", "const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, premultipliedAlpha: false });\n        renderer.setClearColor(0x000000, 0);\n        renderer.setClearAlpha(0);");
          faceHtml = faceHtml.replace("container.appendChild(renderer.domElement);", "renderer.domElement.style.background = 'transparent';\n        renderer.domElement.style.backgroundColor = 'transparent';\n        container.appendChild(renderer.domElement);");
          frame.srcdoc = faceHtml;
        } catch (error) {
          frame.src = `${faceSource}${faceSource.includes("?") ? "&" : "?"}noticeFace=1`;
        }
        taskUserNoticeFace.appendChild(frame);
        return;
        const canvas = document.createElement("canvas");
        canvas.className = "ft-task-ai-face-canvas";
        canvas.setAttribute("aria-hidden", "true");
        taskUserNoticeFace.appendChild(canvas);
        const ctx = canvas.getContext("2d", { alpha: true });
        if (!ctx) {
          return;
        }
        const faceBlocks = [];
        const debrisBlocks = [];
        const eyeBlocks = [];
        const palette = {
          steel: ["#ffffff", "#cccccc", "#2b2f35"],
          darkSteel: ["#d7dee8", "#777f8d", "#111821"],
          orange: ["#fff0d8", "#ff6600", "#3a1200"],
          cyan: ["#eaffff", "#00f2fe", "#062a35"],
          shadow: ["#705c48", "#251409", "#01040f"],
        };
        const seeded = (value) => {
          const wave = Math.sin(value * 12.9898) * 43758.5453;
          return wave - Math.floor(wave);
        };
        const leftEyeX = -1.10;
        const rightEyeX = 1.10;
        const eyeY = 0.70;
        for (let gx = -35; gx <= 35; gx += 1) {
          for (let gy = -45; gy <= 38; gy += 1) {
            const nx = gx / 35;
            const ny = gy / 38;
            let jawCurve = 1;
            if (ny < 0) {
              jawCurve = 1 - Math.abs(ny) * 1.35;
            }
            if (jawCurve < 0.15) {
              continue;
            }
            const boundary = ((nx / jawCurve) * (nx / jawCurve)) + (ny * ny * 0.90);
            if (boundary >= 1) {
              continue;
            }
            if (Math.abs(ny - eyeY / 3.42) < 0.055 && Math.abs(nx) > 0.18 && Math.abs(nx) < 0.55) {
              continue;
            }
            if (Math.abs(nx) > 0.28 && Math.abs(nx) < 0.34 && ny > 0.10) {
              continue;
            }
            let z = Math.sqrt(1 - boundary) * 5.3;
            const isNose = Math.abs(nx) < 0.14 && ny > -0.10 && ny < 0.45;
            const isJaw = ny < -0.22;
            if (isNose) {
              z += 0.45;
            }
            const seed = seeded(gx * 71 + gy * 131);
            const material = seed > 0.84 || Math.abs(nx) < 0.020 ? "orange" : (seed > 0.72 ? "darkSteel" : "steel");
            faceBlocks.push({
              x: gx * 0.090,
              y: gy * 0.090,
              z,
              material,
              phase: faceBlocks.length * 0.073 + seed * 4,
              scale: 0.84 + seed * 0.24,
              blockSize: 0.080,
              jaw: isJaw,
            });
          }
        }
        for (let i = 0; i < 260; i += 1) {
          const seed = seeded(i * 19 + 7);
          const angle = seeded(i * 31 + 3) * Math.PI * 2;
          debrisBlocks.push({
            angle,
            radius: 3.3 + seeded(i * 43 + 11) * 2.5,
            baseZ: (seeded(i * 53 + 5) - 0.5) * 4.0,
            speed: 0.15 + seeded(i * 61 + 17) * 0.40,
            floatSpeed: 0.80 + seeded(i * 67 + 23) * 2.0,
            seed: seed * 80,
            scale: 0.82 + seeded(i * 79 + 29) * 0.75,
            blockSize: 0.030 + seeded(i * 83 + 31) * 0.060,
            material: seed > 0.40 ? "steel" : "orange",
          });
        }
        [-1, 1].forEach((side) => {
          for (let ex = -3; ex <= 3; ex += 1) {
            eyeBlocks.push({
              x: (side < 0 ? leftEyeX : rightEyeX) + ex * 0.090,
              y: eyeY,
              z: 2.70,
              material: "cyan",
              phase: eyeBlocks.length * 0.21,
              scale: ex === 0 ? 1.22 : 0.98,
              blockSize: 0.145,
            });
          }
        });
        const resize = () => {
          const rect = canvas.getBoundingClientRect();
          const dpr = Math.min(window.devicePixelRatio || 1, 1.75);
          const width = Math.max(1, Math.floor(rect.width * dpr));
          const height = Math.max(1, Math.floor(rect.height * dpr));
          if (canvas.width !== width || canvas.height !== height) {
            canvas.width = width;
            canvas.height = height;
          }
          return { width, height, dpr };
        };
        const project = (panel, time, speech, metrics, options = {}) => {
          const phase = Number.isFinite(panel.phase) ? panel.phase : 0;
          const scale = Number.isFinite(panel.scale) ? panel.scale : 1;
          const yaw = Math.sin(time * 0.15) * 0.22;
          const pitch = Math.cos(time * 0.08) * 0.04;
          let x = Number.isFinite(panel.x) ? panel.x : 0;
          let y = Number.isFinite(panel.y) ? panel.y : 0;
          let z = Number.isFinite(panel.z) ? panel.z : 0;
          if (options.flow) {
            x += Math.sin(time * 2.5 + x * 2.0) * 0.040;
            y += Math.cos(time * 2.0 + y * 2.5) * 0.040;
            if (panel.material === "steel" || panel.material === "darkSteel") {
              z += Math.sin(time * 6.0 + phase) * 0.014;
            }
          }
          if (panel.jaw) {
            y -= speech * 0.28;
            z -= speech * 0.05;
          }
          const cosY = Math.cos(yaw);
          const sinY = Math.sin(yaw);
          const rx = x * cosY - z * sinY;
          let rz = x * sinY + z * cosY;
          const cosX = Math.cos(pitch);
          const sinX = Math.sin(pitch);
          const ry = y * cosX - rz * sinX;
          rz = y * sinX + rz * cosX;
          const unit = Math.min(metrics.width, metrics.height) / 11.8;
          const perspective = 11.5 / (11.5 + rz);
          return {
            x: metrics.width / 2 + rx * unit * perspective,
            y: metrics.height * 0.49 - ry * unit * perspective,
            z: rz,
            size: unit * (panel.blockSize || 0.060) * perspective * scale,
            perspective,
          };
        };
        const drawPanel = (panel, point, lightBoost = 0) => {
          if (!Number.isFinite(point.x) || !Number.isFinite(point.y) || !Number.isFinite(point.size)) {
            return;
          }
          const colors = palette[panel.material] || palette.steel;
          const size = point.size;
          const side = size * 0.42;
          const shade = Math.max(0.52, Math.min(1.35, 0.82 + point.z * 0.042 + lightBoost));
          ctx.save();
          ctx.translate(point.x, point.y);
          ctx.rotate(Math.sin((panel.phase || 0) + point.z) * 0.045);
          ctx.globalAlpha = 0.72 + Math.min(0.26, Math.max(0, point.perspective - 0.55) * 0.6);
          ctx.shadowColor = panel.material === "orange" ? "rgba(255,102,0,0.74)" : (panel.material === "cyan" ? "rgba(0,242,254,0.72)" : "rgba(255,210,160,0.36)");
          ctx.shadowBlur = panel.material === "steel" || panel.material === "darkSteel" ? size * 0.42 : size * 0.95;
          ctx.fillStyle = colors[2];
          ctx.beginPath();
          ctx.moveTo(size / 2, -size / 2);
          ctx.lineTo(size / 2 + side, -size / 2 + side * 0.36);
          ctx.lineTo(size / 2 + side, size / 2 + side * 0.36);
          ctx.lineTo(size / 2, size / 2);
          ctx.closePath();
          ctx.fill();
          const grad = ctx.createLinearGradient(-size / 2, -size / 2, size / 2, size / 2);
          grad.addColorStop(0, colors[0]);
          grad.addColorStop(0.36, colors[1]);
          grad.addColorStop(1, colors[2]);
          ctx.globalAlpha = shade;
          ctx.fillStyle = grad;
          ctx.fillRect(-size / 2, -size / 2, size, size);
          ctx.globalAlpha = 0.52;
          ctx.strokeStyle = panel.material === "orange" ? "rgba(255,170,70,0.76)" : (panel.material === "cyan" ? "rgba(190,255,255,0.84)" : "rgba(255,238,210,0.52)");
          ctx.lineWidth = Math.max(0.55, size * 0.07);
          ctx.strokeRect(-size / 2, -size / 2, size, size);
          ctx.restore();
        };
        const drawHole = (point, rx, ry, alpha = 0.95) => {
          const grad = ctx.createRadialGradient(point.x, point.y, 1, point.x, point.y, rx);
          grad.addColorStop(0, `rgba(0,0,0,${alpha})`);
          grad.addColorStop(0.72, "rgba(0,5,9,0.92)");
          grad.addColorStop(1, "rgba(0,242,254,0.16)");
          ctx.fillStyle = grad;
          ctx.beginPath();
          ctx.ellipse(point.x, point.y, rx, ry, 0, 0, Math.PI * 2);
          ctx.fill();
        };
        taskNoticeFaceScene = {
          canvas,
          lastFrame: 0,
          raf: 0,
          render(time = 0, speaking = false) {
            const metrics = resize();
            ctx.clearRect(0, 0, metrics.width, metrics.height);
            ctx.save();
            ctx.globalCompositeOperation = "source-over";
            const unit = Math.min(metrics.width, metrics.height) / 11.8;
            const speech = speaking ? Math.abs(Math.sin(time * 3.8) * Math.cos(time * 1.2)) : 0;
            const debrisItems = debrisBlocks
              .map((debris) => {
                const angle = debris.angle + time * debris.speed;
                const panel = {
                  x: Math.cos(angle) * debris.radius,
                  y: Math.sin(angle) * debris.radius,
                  z: debris.baseZ + Math.sin(time * debris.floatSpeed + debris.seed) * 0.30,
                  material: debris.material,
                  phase: debris.seed,
                  scale: debris.scale,
                  blockSize: debris.blockSize,
                };
                return { panel, point: project(panel, time, speech, metrics) };
              })
              .sort((a, b) => a.point.z - b.point.z);
            const faceItems = faceBlocks
              .map((panel) => ({ panel, point: project(panel, time, speech, metrics, { flow: true }) }))
              .sort((a, b) => a.point.z - b.point.z);
            debrisItems.filter((item) => item.point.z < 1.2).forEach(({ panel, point }) => drawPanel(panel, point, Math.sin(time * 2 + panel.phase) * 0.08));
            const corePulse = 1.0 + Math.sin(time * 8.0) * 0.12;
            const core = project({ x: 0, y: 0.02, z: -0.80, blockSize: 0.28, scale: corePulse, material: "orange" }, time, 0, metrics);
            const coreRadius = Math.max(18, unit * (0.48 + Math.sin(time * 8.0) * 0.055));
            const coreGrad = ctx.createRadialGradient(core.x, core.y, 1, core.x, core.y, coreRadius);
            coreGrad.addColorStop(0, `rgba(255,102,0,${speaking ? 0.96 : 0.70})`);
            coreGrad.addColorStop(0.40, "rgba(255,51,0,0.42)");
            coreGrad.addColorStop(0.70, "rgba(0,242,254,0.16)");
            coreGrad.addColorStop(1, "rgba(255,102,0,0)");
            ctx.fillStyle = coreGrad;
            ctx.beginPath();
            ctx.arc(core.x, core.y, coreRadius, 0, Math.PI * 2);
            ctx.fill();
            drawPanel({ material: "orange", phase: time * 6, scale: corePulse }, core, 0.34);
            faceItems.forEach(({ panel, point }) => drawPanel(panel, point, Math.sin(time * 2.5 + panel.phase) * 0.10));
            const leftEyeHole = project({ x: leftEyeX, y: eyeY, z: 3.0, blockSize: 0.10 }, time, 0, metrics);
            const rightEyeHole = project({ x: rightEyeX, y: eyeY, z: 3.0, blockSize: 0.10 }, time, 0, metrics);
            drawHole(leftEyeHole, unit * 0.40, unit * 0.095, 0.98);
            drawHole(rightEyeHole, unit * 0.40, unit * 0.095, 0.98);
            drawHole(project({ x: -0.20, y: -0.04, z: 5.7, blockSize: 0.05 }, time, 0, metrics), unit * 0.055, unit * 0.040, 0.98);
            drawHole(project({ x: 0.20, y: -0.04, z: 5.7, blockSize: 0.05 }, time, 0, metrics), unit * 0.055, unit * 0.040, 0.98);
            const eyeLookX = Math.floor(Math.sin(time * 2.0) * 3) * 0.050;
            eyeBlocks
              .map((eye) => {
                const panel = { ...eye, x: eye.x + eyeLookX };
                return { panel, point: project(panel, time, speech, metrics) };
              })
              .sort((a, b) => a.point.z - b.point.z)
              .forEach(({ panel, point }) => drawPanel(panel, point, 0.24));
            const reactorVent = project({ x: 0, y: -0.62 - speech * 0.08, z: 4.05, blockSize: 0.10 }, time, 0, metrics);
            drawHole(reactorVent, unit * 0.32, unit * (0.070 + speech * 0.035), 0.93);
            const ventGlowRadius = Math.max(7, unit * (0.15 + speech * 0.05));
            const ventGlow = ctx.createRadialGradient(reactorVent.x, reactorVent.y, 1, reactorVent.x, reactorVent.y, ventGlowRadius);
            ventGlow.addColorStop(0, `rgba(255,102,0,${speaking ? 0.98 : 0.62})`);
            ventGlow.addColorStop(0.48, "rgba(255,51,0,0.42)");
            ventGlow.addColorStop(1, "rgba(0,242,254,0)");
            ctx.fillStyle = ventGlow;
            ctx.beginPath();
            ctx.arc(reactorVent.x, reactorVent.y, ventGlowRadius, 0, Math.PI * 2);
            ctx.fill();
            debrisItems.filter((item) => item.point.z >= 1.2).forEach(({ panel, point }) => drawPanel(panel, point, Math.sin(time * 2.2 + panel.phase) * 0.10));
            ctx.globalCompositeOperation = "lighter";
            ctx.strokeStyle = "rgba(255,102,0,0.34)";
            ctx.lineWidth = Math.max(1, unit * 0.018);
            ctx.beginPath();
            ctx.ellipse(metrics.width / 2, metrics.height * 0.49, unit * 3.92, unit * 4.52, Math.sin(time * 0.18) * 0.16, 0.2, Math.PI * 1.55);
            ctx.stroke();
            ctx.strokeStyle = "rgba(0,242,254,0.28)";
            ctx.lineWidth = Math.max(1, unit * 0.010);
            ctx.beginPath();
            ctx.ellipse(metrics.width / 2, metrics.height * 0.49, unit * 4.64, unit * 4.08, -Math.sin(time * 0.13) * 0.12, -0.3, Math.PI * 1.24);
            ctx.stroke();
            ctx.restore();
          },
        };
      };

      const fillTaskNoticeEditor = (notice = {}) => {
        taskNoticeEditId = clean(notice.id || "");
        const noticeLanguage = clean(notice.language || "vi") === "en" ? "en" : "vi";
        const noticeText = preserveQuestionText(notice.text || "");
        const englishText = taskNoticeEnglishTranslation(notice) || (noticeLanguage === "en" ? noticeText : "");
        const vietnameseText = taskNoticeVietnameseTranslation(notice) || (noticeLanguage === "vi" ? noticeText : "");
        if (taskNoticeTextEn) taskNoticeTextEn.value = englishText;
        if (taskNoticeTextVi) taskNoticeTextVi.value = vietnameseText;
        if (taskNoticeName) taskNoticeName.value = clean(notice.speaker_name || "");
        if (taskNoticeAvatar) taskNoticeAvatar.value = clean(notice.avatar || "");
        taskNoticeSetActiveLanguage(noticeLanguage);
        if (taskNoticeStyle) taskNoticeStyle.value = normalizeTaskNoticeStyle(notice.notice_style || notice.noticeStyle || notice.style);
        renderTaskNoticeVoiceSelect();
        const activeVoice = taskNoticeActiveVoiceNode();
        if (activeVoice && clean(notice.voice || "")) {
          const hasVoice = Array.from(activeVoice.options || []).some((option) => option.value === notice.voice);
          if (!hasVoice) {
            const option = document.createElement("option");
            option.value = notice.voice;
            option.textContent = clean(notice.voice_label || notice.voice);
            activeVoice.appendChild(option);
          }
          activeVoice.value = notice.voice;
          syncTaskNoticeLegacyFields();
        }
        if (taskNoticeOnce) taskNoticeOnce.checked = clean(notice.mode || "once") === "once";
        if (taskNoticeDay) taskNoticeDay.checked = clean(notice.mode || "once") === "day";
        if (taskNoticeAlways) taskNoticeAlways.checked = clean(notice.mode || "once") === "always";
        if (taskNoticeRepeatCount) taskNoticeRepeatCount.value = String(Math.max(0, Math.min(999, Number(notice.repeat_limit || notice.repeatLimit || notice.max_shows || 0) || 0)));
        if (taskNoticeBackGap) taskNoticeBackGap.value = String(Math.max(1, Math.min(99, Number(notice.back_interval || notice.backInterval || notice.back_gap || 1) || 1)));
        if (taskNoticeUntilComplete) taskNoticeUntilComplete.checked = Boolean(notice.until_tasks_complete || notice.untilTasksComplete || notice.until_complete);
        if (taskNoticeAudio) taskNoticeAudio.checked = Boolean(notice.audio_enabled);
        if (taskNoticeAck) taskNoticeAck.checked = Boolean(notice.require_ack);
        if (taskNoticeAdd) taskNoticeAdd.textContent = "Save notice";
        taskNoticeSetState("Editing notice");
      };

      const taskNoticeAdminAvailable = (payload = currentTaskPayload) => {
        const owner = clean((payload && payload.task_owner) || serverTaskOwnerContext || "");
        return Boolean(payload && payload.admin && owner && taskNoticeAdmin);
      };

      const syncTaskNoticeToggleButton = (available = taskNoticeAdminAvailable()) => {
        if (!taskNoticeToggleButton) {
          return;
        }
        taskNoticeToggleButton.hidden = !available;
        taskNoticeToggleButton.disabled = !available;
        taskNoticeToggleButton.textContent = taskNoticeAdminOpen ? "Hide notice" : "Task notice";
        taskNoticeToggleButton.title = taskNoticeAdminOpen ? "Hide the floating Task Notice popup." : "Show the floating Task Notice popup.";
        taskNoticeToggleButton.setAttribute("aria-expanded", taskNoticeAdminOpen ? "true" : "false");
      };

      const setTaskNoticeAdminOpen = (open = false, options = {}) => {
        const available = taskNoticeAdminAvailable();
        taskNoticeAdminOpen = Boolean(open && available);
        if (taskNoticeAdmin) {
          taskNoticeAdmin.hidden = !taskNoticeAdminOpen;
        }
        if (serverBrowserLayout) {
          serverBrowserLayout.classList.remove("has-task-notice-admin", "is-panel-notice");
          serverBrowserLayout.classList.toggle("has-task-notice-popup", taskNoticeAdminOpen);
        }
        syncTaskNoticeToggleButton(available);
        if (taskNoticeAdminOpen && options && options.focus) {
          const focusTarget = taskNoticeTextVi || taskNoticeTextEn || taskNoticeName || taskNoticeAdmin;
          if (focusTarget && focusTarget.focus) {
            window.setTimeout(() => focusTarget.focus({ preventScroll: true }), 80);
          }
        }
      };

      const renderTaskNoticeAdmin = (payload = {}) => {
        const owner = clean(payload.task_owner || serverTaskOwnerContext || "");
        const isVisible = Boolean(payload.admin && owner && taskNoticeAdmin);
        const previousPayload = currentTaskPayload;
        currentTaskPayload = { ...currentTaskPayload, ...payload, task_owner: owner, admin: Boolean(payload.admin) };
        setTaskNoticeAdminOpen(taskNoticeAdminOpen && isVisible);
        currentTaskPayload = previousPayload;
        syncServerBrowserTabs();
        if (!isVisible) {
          taskNoticeAdminOpen = false;
          setTaskNoticeAdminOpen(false);
          syncTaskNoticeToggleButton(false);
          return;
        }
        if (!taskNoticeEditId) {
          if (taskNoticeName && !clean(taskNoticeName.value)) {
            taskNoticeName.value = taskNoticeProfile.speaker_name || "";
          }
          if (taskNoticeAvatar && !clean(taskNoticeAvatar.value)) {
            taskNoticeAvatar.value = taskNoticeProfile.avatar || "";
          }
          if (taskNoticeStyle) {
            taskNoticeStyle.value = normalizeTaskNoticeStyle(taskNoticeProfile.notice_style || "hologram");
          }
          if (taskNoticeLanguage) {
            taskNoticeLanguage.value = taskNoticeProfile.active_language === "en" ? "en" : "vi";
          }
          if (taskNoticeTextEn && !preserveQuestionText(taskNoticeTextEn.value)) {
            taskNoticeTextEn.value = taskNoticeProfile.draft_text_en || "";
          }
          if (taskNoticeTextVi && !preserveQuestionText(taskNoticeTextVi.value)) {
            taskNoticeTextVi.value = taskNoticeProfile.draft_text_vi || taskNoticeProfile.draft_text || "";
          }
          taskNoticeSetActiveLanguage(taskNoticeLanguage && taskNoticeLanguage.value === "en" ? "en" : "vi");
        }
        void loadTaskNoticeVoiceOptions();
        const notices = Array.isArray(payload.task_notices) ? payload.task_notices : [];
        if (!taskNoticeList) {
          return;
        }
        taskNoticeList.textContent = "";
        if (!notices.length) {
          const empty = document.createElement("div");
          empty.className = "ft-task-empty";
          empty.textContent = "No learner notices yet.";
          taskNoticeList.appendChild(empty);
          return;
        }
        notices.slice().reverse().forEach((notice) => {
          const card = document.createElement("article");
          card.className = "ft-task-notice-card";
          const head = document.createElement("div");
          head.className = "ft-task-notice-card-head";
          const speaker = document.createElement("div");
          speaker.className = "ft-task-notice-speaker";
          const avatar = document.createElement("span");
          avatar.className = "ft-task-notice-avatar-dot";
          const avatarUrl = taskNoticeAvatarUrl(notice.avatar || "");
          if (avatarUrl) {
            const img = document.createElement("img");
            img.src = avatarUrl;
            img.alt = "";
            avatar.appendChild(img);
          }
          const label = document.createElement("span");
          label.textContent = clean(notice.speaker_name || "Teacher notice");
          speaker.append(avatar, label);
          const actions = document.createElement("div");
          actions.className = "ft-task-notice-card-actions";
          const edit = document.createElement("button");
          edit.type = "button";
          edit.textContent = "Edit";
          edit.addEventListener("click", () => fillTaskNoticeEditor(notice));
          const remove = document.createElement("button");
          remove.type = "button";
          remove.textContent = "Remove";
          remove.addEventListener("click", () => void removeTaskNotice(notice.id));
          actions.append(edit, remove);
          head.append(speaker, actions);
          const noticeLanguage = clean(notice.language) === "en" ? "en" : "vi";
          const noticeText = preserveQuestionText(notice.text || "");
          const englishText = taskNoticeEnglishTranslation(notice) || (noticeLanguage === "en" ? noticeText : "");
          const vietnameseText = taskNoticeVietnameseTranslation(notice) || (noticeLanguage === "vi" ? noticeText : "");
          const text = document.createElement("p");
          text.className = "ft-task-notice-card-text";
          text.textContent = `English: ${englishText || "Pending translation"}`;
          const translation = vietnameseText;
          const translationText = document.createElement("p");
          translationText.className = "ft-task-notice-card-text is-translation";
          translationText.textContent = translation ? `Vietnamese: ${translation}` : "";
          const chips = document.createElement("div");
          chips.className = "ft-task-notice-chip-row";
          chips.appendChild(createServerChip(noticeLanguage === "en" ? "Audio English" : "Audio Vietnamese", "filetype"));
          if (englishText && vietnameseText) {
            chips.appendChild(createServerChip("Bilingual", "shared"));
          }
          chips.appendChild(createServerChip(taskNoticeStyleLabel(notice.notice_style || notice.noticeStyle || notice.style), "shared"));
          chips.appendChild(createServerChip(clean(notice.mode) === "always" ? "Every login" : (clean(notice.mode) === "day" ? "1 day" : "Show once"), "date"));
          const repeatLimit = Math.max(0, Number(notice.repeat_limit || notice.repeatLimit || notice.max_shows || 0) || 0);
          const backInterval = Math.max(1, Number(notice.back_interval || notice.backInterval || notice.back_gap || 1) || 1);
          if (repeatLimit > 0) {
            chips.appendChild(createServerChip(`${repeatLimit} shows`, "date"));
          }
          if (backInterval > 1) {
            chips.appendChild(createServerChip(`Every ${backInterval} backs`, "shared"));
          }
          if (notice.until_tasks_complete || notice.untilTasksComplete || notice.until_complete) {
            chips.appendChild(createServerChip("Until complete", "total"));
          }
          if (notice.audio_enabled) {
            chips.appendChild(createServerChip("Voice", "learned"));
          }
          if (notice.require_ack) {
            chips.appendChild(createServerChip("Require read", "total"));
          }
          if (notice.read_at) {
            chips.appendChild(createServerChip("Read", "learned"));
          }
          card.append(head, text);
          if (translation) {
            card.appendChild(translationText);
          }
          card.appendChild(chips);
          taskNoticeList.appendChild(card);
        });
      };

      const buildTaskNoticePayload = (action = "save") => {
        syncTaskNoticeLegacyFields();
        const language = taskNoticeActiveLanguage();
        const activeVoice = taskNoticeActiveVoiceNode();
        const option = activeVoice && activeVoice.options ? activeVoice.options[activeVoice.selectedIndex] : null;
        const textEn = preserveQuestionText(taskNoticeTextEn ? taskNoticeTextEn.value || "" : "");
        const textVi = preserveQuestionText(taskNoticeTextVi ? taskNoticeTextVi.value || "" : "");
        return {
          action,
          user: clean(serverTaskOwnerContext),
          id: taskNoticeEditId,
          text: language === "en" ? textEn : textVi,
          language,
          voice: activeVoice ? activeVoice.value : "",
          voice_label: option ? option.textContent || "" : "",
          translation_en: textEn,
          translation_vi: textVi,
          notice_style: taskNoticeStyle ? taskNoticeStyle.value : "hologram",
          speaker_name: taskNoticeName ? taskNoticeName.value : "",
          avatar: taskNoticeAvatar ? taskNoticeAvatar.value : "",
          mode: taskNoticeDay && taskNoticeDay.checked ? "day" : (taskNoticeAlways && taskNoticeAlways.checked ? "always" : "once"),
          repeat_limit: Math.max(0, Math.min(999, Number(taskNoticeRepeatCount ? taskNoticeRepeatCount.value : 0) || 0)),
          back_interval: Math.max(1, Math.min(99, Number(taskNoticeBackGap ? taskNoticeBackGap.value : 1) || 1)),
          until_tasks_complete: Boolean(taskNoticeUntilComplete && taskNoticeUntilComplete.checked),
          audio_enabled: Boolean(taskNoticeAudio && taskNoticeAudio.checked),
          require_ack: Boolean(taskNoticeAck && taskNoticeAck.checked),
        };
      };

      const saveTaskNotice = async (options = {}) => {
        const sendNow = Boolean(options.sendNow);
        const owner = clean(serverTaskOwnerContext);
        if (!owner || (!taskNoticeTextEn && !taskNoticeTextVi)) {
          return;
        }
        const text = preserveQuestionText((taskNoticeActiveTextNode() || {}).value || "");
        if (!text) {
          taskNoticeSetState("Message is empty.", true);
          return;
        }
        if (taskNoticeAdd) {
          taskNoticeAdd.disabled = true;
          taskNoticeAdd.textContent = taskNoticeAudio && taskNoticeAudio.checked ? "Creating voice" : "Saving";
        }
        if (taskNoticeSendNow) {
          taskNoticeSendNow.disabled = true;
          taskNoticeSendNow.textContent = sendNow ? "Sending" : "Send now";
        }
        taskNoticeSetState(sendNow
          ? (taskNoticeAudio && taskNoticeAudio.checked ? "Creating voice and sending now..." : "Sending notice now...")
          : (taskNoticeAudio && taskNoticeAudio.checked ? "Creating voice audio..." : "Saving notice..."));
        try {
          const translated = await ensureTaskNoticeMirrorTranslation();
          if (!translated) {
            return;
          }
          const result = await fetchAuthJson("/lesson-task-notices", {
            method: "POST",
            body: JSON.stringify(buildTaskNoticePayload(sendNow ? "send_now" : "save")),
          });
          taskNoticeProfile = currentTaskNoticeProfilePayload();
          void syncTaskNoticeProfilePreference();
          if (sendNow) {
            const payload = result.payload || {};
            const targetName = clean(payload.target_user || owner);
            taskNoticeSetState(payload.target_online === false
              ? `Sent to ${targetName}, but this learner is not reporting online yet.`
              : `Sent directly to ${targetName}.`);
          } else {
            currentTaskPayload.task_notices = Array.isArray(result.payload && result.payload.task_notices) ? result.payload.task_notices : currentTaskPayload.task_notices;
            renderTaskNoticeAdmin({ ...currentTaskPayload, ...result.payload, admin: true });
            resetTaskNoticeEditor();
            taskNoticeSetState("Notice saved.");
          }
        } catch (error) {
          taskNoticeSetState(error && error.message ? error.message : (sendNow ? "Could not send notice." : "Could not save notice."), true);
        } finally {
          if (taskNoticeAdd) {
            taskNoticeAdd.disabled = false;
            taskNoticeAdd.textContent = taskNoticeEditId ? "Save notice" : "Add notice";
          }
          if (taskNoticeSendNow) {
            taskNoticeSendNow.disabled = false;
            taskNoticeSendNow.textContent = "Send now";
          }
        }
      };

      const removeTaskNotice = async (id = "") => {
        const owner = clean(serverTaskOwnerContext);
        const noticeId = clean(id);
        if (!owner || !noticeId) {
          return;
        }
        taskNoticeSetState("Removing notice...");
        try {
          const result = await fetchAuthJson("/lesson-task-notices", {
            method: "POST",
            body: JSON.stringify({ action: "remove", user: owner, id: noticeId }),
          });
          currentTaskPayload.task_notices = Array.isArray(result.payload && result.payload.task_notices) ? result.payload.task_notices : currentTaskPayload.task_notices;
          renderTaskNoticeAdmin({ ...currentTaskPayload, ...result.payload, admin: true });
          if (taskNoticeEditId === noticeId) {
            resetTaskNoticeEditor();
          }
          taskNoticeSetState("Notice removed.");
        } catch (error) {
          taskNoticeSetState(error && error.message ? error.message : "Could not remove notice.", true);
        }
      };

      const uploadTaskNoticeAvatar = async () => {
        const file = taskNoticeAvatarFile && taskNoticeAvatarFile.files ? taskNoticeAvatarFile.files[0] : null;
        if (!file) {
          return;
        }
        taskNoticeSetState("Uploading avatar...");
        if (taskNoticeAvatarUpload) {
          taskNoticeAvatarUpload.disabled = true;
          taskNoticeAvatarUpload.textContent = "Uploading";
        }
        try {
          const form = new FormData();
          form.append("file", file);
          const result = await fetchAuthForm("/lesson-task-notice-avatar", form);
          const avatarPath = clean(result.payload && (result.payload.avatar || result.payload.path));
          if (taskNoticeAvatar && avatarPath) {
            taskNoticeAvatar.value = avatarPath;
          }
          taskNoticeProfile = currentTaskNoticeProfilePayload();
          void syncTaskNoticeProfilePreference();
          taskNoticeSetState("Avatar uploaded.");
        } catch (error) {
          taskNoticeSetState(error && error.message ? error.message : "Could not upload avatar.", true);
        } finally {
          if (taskNoticeAvatarUpload) {
            taskNoticeAvatarUpload.disabled = false;
            taskNoticeAvatarUpload.textContent = "Upload";
          }
          if (taskNoticeAvatarFile) {
            taskNoticeAvatarFile.value = "";
          }
        }
      };

      const buildTaskNoticePreviewPayload = () => {
        syncTaskNoticeLegacyFields();
        const language = taskNoticeActiveLanguage();
        const activeVoice = taskNoticeActiveVoiceNode();
        const option = activeVoice && activeVoice.options ? activeVoice.options[activeVoice.selectedIndex] : null;
        const textEn = preserveQuestionText(taskNoticeTextEn ? taskNoticeTextEn.value : "");
        const textVi = preserveQuestionText(taskNoticeTextVi ? taskNoticeTextVi.value : "");
        return {
          id: `preview-${Date.now()}`,
          text: (language === "en" ? textEn : textVi) || "AI notice preview. Task channel is ready.",
          language,
          voice: activeVoice ? activeVoice.value : "",
          voice_label: option ? option.textContent || "" : (language === "en" ? "English preview voice" : "Vietnamese preview voice"),
          translation_en: textEn || (language === "en" ? "AI notice preview. Task channel is ready." : ""),
          translation_vi: textVi || (language === "vi" ? "Kênh thông báo đã sẵn sàng." : ""),
          notice_style: taskNoticeStyle ? taskNoticeStyle.value : "hologram",
          speaker_name: clean(taskNoticeName ? taskNoticeName.value : "") || taskNoticeProfile.speaker_name || "Teacher notice",
          avatar: clean(taskNoticeAvatar ? taskNoticeAvatar.value : "") || taskNoticeProfile.avatar || "",
          mode: "always",
          audio_enabled: false,
          require_ack: false,
          _preview: true,
        };
      };

      const previewTaskNoticeStyle = async () => {
        taskUserNoticeQueue = [];
        taskUserNoticePlaying = false;
        if (!(await ensureTaskNoticeMirrorTranslation())) {
          return;
        }
        taskNoticeSetState("Previewing notice style.");
        void showTaskUserNotice(buildTaskNoticePreviewPayload(), { preview: true });
      };

      const markTaskUserNoticeRead = async (notice = {}) => {
        const id = clean(notice.id || "");
        if (!id || !authToken || notice._immediate) {
          return;
        }
        try {
          await fetchAuthJson("/lesson-task-notices", {
            method: "POST",
            body: JSON.stringify({ action: "read", id }),
          });
        } catch (error) {
        }
      };

      const markTaskUserNoticeSeen = async (notice = {}) => {
        const id = clean(notice.id || "");
        if (!id || !authToken || notice._immediate) {
          return;
        }
        try {
          await fetchAuthJson("/lesson-task-notices", {
            method: "POST",
            body: JSON.stringify({ action: "seen", id }),
          });
        } catch (error) {
        }
      };

      const setGhostAiFocusMode = (active) => {
        document.documentElement.classList.toggle("ft-ghost-ai-focus", Boolean(active));
      };
